<?php if(!defined('ABSPATH'))exit; global $wpdb;
$v=ICD_Visitas_Database::table('visitas');$e=ICD_Visitas_Database::table('escolas');$m=ICD_Visitas_Database::table('mediadores');$p=ICD_Visitas_Database::table('participantes');$mun=ICD_Visitas_Database::table('municipios');$pg=ICD_Visitas_Database::table('pedagogas');$vp=ICD_Visitas_Database::table('visita_pedagogas');
$from=sanitize_text_field($_GET['de']??date('Y-01-01'));$to=sanitize_text_field($_GET['ate']??current_time('Y-m-d'));$school=absint($_GET['escola']??0);$mid=absint($_GET['mediador']??0);$pid=absint($_GET['pedagoga']??0);$municipio=absint($_GET['municipio']??0);$status=sanitize_key($_GET['status']??'realizada');$turno=sanitize_key($_GET['turno']??'');
$where=['v.data_visita BETWEEN %s AND %s'];$args=[$from,$to];$joins=" JOIN $e e ON e.id=v.escola_id LEFT JOIN $mun mu ON mu.id=e.municipio_id ";if($status){$where[]='v.status=%s';$args[]=$status;}if($turno){$where[]='v.turno=%s';$args[]=$turno;}if($school){$where[]='v.escola_id=%d';$args[]=$school;}if($municipio){$where[]='e.municipio_id=%d';$args[]=$municipio;}if($mid){$joins.=" JOIN $p pf ON pf.visita_id=v.id ";$where[]='pf.mediador_id=%d';$args[]=$mid;}if($pid){$joins.=" JOIN $vp vpf ON vpf.visita_id=v.id ";$where[]='vpf.pedagoga_id=%d';$args[]=$pid;}$sqlwhere=implode(' AND ',$where);$base="FROM $v v $joins WHERE $sqlwhere";
$total=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT v.id) $base",...$args));$schools=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT v.escola_id) $base",...$args));$medCount=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT pp.mediador_id) FROM $p pp JOIN $v v ON v.id=pp.visita_id $joins WHERE $sqlwhere",...$args));$pedCount=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT vpp.pedagoga_id) FROM $vp vpp JOIN $v v ON v.id=vpp.visita_id $joins WHERE $sqlwhere",...$args));
$months=$wpdb->get_results($wpdb->prepare("SELECT DATE_FORMAT(v.data_visita,'%Y-%m') mes,COUNT(DISTINCT v.id) total $base GROUP BY mes ORDER BY mes",...$args));$rank=$wpdb->get_results($wpdb->prepare("SELECT e.id,e.nome,COUNT(DISTINCT v.id) total $base GROUP BY e.id,e.nome ORDER BY total DESC,e.nome LIMIT 12",...$args));
$allSchools=$wpdb->get_results("SELECT id,nome FROM $e WHERE ativo=1 ORDER BY nome");$allMeds=$wpdb->get_results("SELECT id,nome FROM $m WHERE ativo=1 ORDER BY nome");$allPeds=$wpdb->get_results("SELECT id,nome FROM $pg WHERE ativo=1 ORDER BY nome");$allMun=$wpdb->get_results("SELECT id,nome FROM $mun WHERE ativo=1 ORDER BY nome");$max=1;foreach($months as $x)$max=max($max,(int)$x->total);?>
<div class="wrap icd-admin"><div class="icd-title"><img src="<?php echo esc_url(ICD_VISITAS_URL.'assets/logo.svg');?>" alt=""><div><h1>Dashboard de Visitas Pedagógicas</h1><p>Instituto Caminho de Davi</p></div></div><form class="icd-filters" method="get"><?php ICD_Visitas_Helpers::page_input('icd-visitas'); ?><label>De<input type="date" name="de" value="<?php echo esc_attr($from);?>"></label><label>Até<input type="date" name="ate" value="<?php echo esc_attr($to);?>"></label><label>Município<select name="municipio"><option value="0">Todos</option><?php foreach($allMun as $x)echo '<option value="'.$x->id.'" '.selected($municipio,$x->id,false).'>'.esc_html($x->nome).'</option>';?></select></label><label>Escola<select name="escola"><option value="0">Todas</option><?php foreach($allSchools as $x)echo '<option value="'.$x->id.'" '.selected($school,$x->id,false).'>'.esc_html($x->nome).'</option>';?></select></label><label>Mediador acompanhado<select name="mediador"><option value="0">Todos</option><?php foreach($allMeds as $x)echo '<option value="'.$x->id.'" '.selected($mid,$x->id,false).'>'.esc_html($x->nome).'</option>';?></select></label><label>Pedagoga<select name="pedagoga"><option value="0">Todas</option><?php foreach($allPeds as $x)echo '<option value="'.$x->id.'" '.selected($pid,$x->id,false).'>'.esc_html($x->nome).'</option>';?></select></label><label>Status<select name="status"><option value="">Todos</option><?php foreach(['realizada','programada','confirmada','nao_realizada','cancelada','reagendada'] as $st)echo '<option value="'.$st.'" '.selected($status,$st,false).'>'.esc_html(ICD_Visitas_Helpers::status_label($st)).'</option>';?></select></label><label>Turno<select name="turno"><option value="">Todos</option><?php foreach(['manha','tarde','noite','integral'] as $tr)echo '<option value="'.$tr.'" '.selected($turno,$tr,false).'>'.esc_html(ICD_Visitas_Helpers::turno_label($tr)).'</option>';?></select></label><button class="button button-primary">Aplicar filtros</button></form><div class="icd-kpis"><div><strong><?php echo $total;?></strong><span>Visitas</span></div><div><strong><?php echo $schools;?></strong><span>Escolas atendidas</span></div><div><strong><?php echo $medCount;?></strong><span>Mediadores acompanhados</span></div><div><strong><?php echo $pedCount;?></strong><span>Pedagogas em campo</span></div></div><div class="icd-grid"><section class="icd-panel"><h2>Visitas por mês</h2><div class="icd-chart-bars"><?php foreach($months as $x):$h=max(6,round(($x->total/$max)*180));?><div class="icd-col"><b><?php echo (int)$x->total;?></b><i style="height:<?php echo $h;?>px"></i><span><?php echo esc_html(date_i18n('M/y',strtotime($x->mes.'-01')));?></span></div><?php endforeach;?></div><?php if(!$months):?><p class="icd-empty">Nenhuma visita no período.</p><?php endif;?></section><section class="icd-panel"><h2>Visitas por escola</h2><?php foreach($rank as $r):?><button type="button" class="icd-rank icd-school-calendar-open" data-school-id="<?php echo (int)$r->id;?>" data-school-name="<?php echo esc_attr($r->nome);?>"><span><?php echo esc_html($r->nome);?></span><b><?php echo (int)$r->total;?></b></button><?php endforeach;?></section></div>
<div class="icd-modal" id="icd-school-calendar-modal" aria-hidden="true"><div class="icd-modal-backdrop" data-icd-close-modal></div><div class="icd-modal-dialog" role="dialog" aria-modal="true" aria-labelledby="icd-calendar-title"><button type="button" class="icd-modal-close" data-icd-close-modal aria-label="Fechar">×</button><div class="icd-calendar-head"><div><h2 id="icd-calendar-title">Calendário de visitas</h2><p id="icd-calendar-school"></p></div><div class="icd-calendar-nav"><button type="button" class="button" id="icd-calendar-prev">‹</button><strong id="icd-calendar-month"></strong><button type="button" class="button" id="icd-calendar-next">›</button></div></div><div class="icd-calendar-weekdays"><span>Dom</span><span>Seg</span><span>Ter</span><span>Qua</span><span>Qui</span><span>Sex</span><span>Sáb</span></div><div class="icd-calendar-grid" id="icd-calendar-grid"></div><div class="icd-calendar-details" id="icd-calendar-details"><p class="icd-empty">Clique em um dia verde para ver as visitas.</p></div></div></div></div>
